# Generated by `mix exhibit.build_runner` from lib/exhibit/parser.ex, lib/exhibit/output.ex, lib/exhibit/runner.ex.
# Do not edit by hand. Runs inside a target project, with no dependency on
# exhibit:
#
#     MIX_ENV=test mix run priv/runner.exs NOTEBOOK.livemd
#
# Evaluates every Elixir cell in order and writes Livebook-format outputs
# back into the notebook. Exits 1 if a cell fails.

defmodule Exhibit.Runner.Parser do
  @moduledoc """
  Splits a Livebook `.livemd` file into an ordered list of blocks and
  renders a list of blocks back into a file.

  Two kinds of block:

    * `%{type: :markdown, lines: [String.t()]}`: anything that is not an
      Elixir cell or a persisted output. Kept byte for byte.
    * `%{type: :cell, metadata: [String.t()], fence: String.t(),
      source_lines: [String.t()], source: String.t(), line: pos_integer(),
      outputs: [String.t()]}`: an Elixir code cell. `metadata` holds any
      `<!-- livebook:{...} -->` comment (and the blank lines after it) that
      sat directly before the fence. `line` is the 1-based line of the
      first line of source. `outputs` are the persisted text outputs that
      followed the cell, already in the form Livebook stores them.

  Output blocks are attached to the cell they follow, so a caller that
  regenerates outputs replaces `outputs` and the blank lines that separated
  them from the cell are reproduced by `render/1`.

  An Elixir fence preceded by `<!-- livebook:{"force_markdown":true} -->`
  is a code sample inside a markdown cell, not a cell, and is kept as
  markdown.
  """

  @type markdown :: %{type: :markdown, lines: [String.t()]}
  @type cell :: %{
          type: :cell,
          metadata: [String.t()],
          fence: String.t(),
          source_lines: [String.t()],
          source: String.t(),
          line: pos_integer(),
          outputs: [String.t()]
        }
  @type block :: markdown | cell

  @output_comment ~s(<!-- livebook:{"output":true} -->)
  @force_markdown ~s(<!-- livebook:{"force_markdown":true} -->)
  @elixir_fence ~r/^(`{3,})elixir\s*$/
  @plain_fence ~r/^(`{3,})\s*$/
  @any_fence ~r/^(`{3,})/
  @metadata_comment ~r/^<!-- livebook:\{.*\} -->\s*$/

  @doc "Parses a notebook into blocks."
  @spec parse(String.t()) :: [block]
  def parse(source) when is_binary(source) do
    source
    |> String.split("\n")
    |> Enum.with_index(1)
    |> tokens([])
    |> group([])
  end

  @doc "Renders blocks back into a notebook."
  @spec render([block]) :: String.t()
  def render(blocks) do
    blocks
    |> Enum.flat_map(&block_lines/1)
    |> Enum.join("\n")
  end

  @doc "The Elixir cells of a parsed notebook, in order."
  @spec cells([block]) :: [cell]
  def cells(blocks), do: Enum.filter(blocks, &(&1.type == :cell))

  # -- tokenising --------------------------------------------------------

  defp tokens([], acc), do: Enum.reverse(acc)

  defp tokens([{@output_comment, _} | rest] = all, acc) do
    case take_output(rest) do
      {:ok, text, rest} -> tokens(rest, [{:output, text} | acc])
      :error -> markdown_line(all, acc)
    end
  end

  # A code sample inside a markdown cell. The comment and the blank lines
  # after it are markdown, and so is the fence that follows.
  defp tokens([{@force_markdown, _} | _] = all, acc) do
    {rest, acc} = markdown_through_blanks(all, acc)

    case rest do
      [{line, _} | _] ->
        if Regex.match?(@any_fence, line), do: fenced_markdown(rest, acc), else: tokens(rest, acc)

      [] ->
        tokens([], acc)
    end
  end

  defp tokens([{line, _} | rest] = all, acc) do
    cond do
      Regex.match?(@metadata_comment, line) and elixir_fence_after_blanks?(rest) ->
        {blanks, rest} = Enum.split_while(rest, fn {l, _} -> l == "" end)
        metadata = [line | Enum.map(blanks, &elem(&1, 0))]
        tokens_cell(rest, metadata, acc)

      Regex.match?(@elixir_fence, line) ->
        tokens_cell(all, [], acc)

      Regex.match?(@any_fence, line) ->
        fenced_markdown(all, acc)

      true ->
        markdown_line(all, acc)
    end
  end

  defp markdown_line([{line, _} | rest], acc), do: tokens(rest, [{:md, line} | acc])

  defp markdown_through_blanks([{line, _} | rest], acc) do
    {blanks, rest} = Enum.split_while(rest, fn {l, _} -> l == "" end)
    acc = Enum.reduce(blanks, [{:md, line} | acc], fn {l, _}, acc -> [{:md, l} | acc] end)
    {rest, acc}
  end

  defp elixir_fence_after_blanks?(lines) do
    case Enum.drop_while(lines, fn {l, _} -> l == "" end) do
      [{line, _} | _] -> Regex.match?(@elixir_fence, line)
      [] -> false
    end
  end

  defp tokens_cell([{open, n} | rest], metadata, acc) do
    [_, fence] = Regex.run(@elixir_fence, open)
    {body, rest} = take_until_fence(rest, fence)

    rest =
      case rest do
        [{_close, _} | rest] -> rest
        [] -> raise ArgumentError, "unterminated elixir cell opened on line #{n}"
      end

    cell = %{
      type: :cell,
      metadata: metadata,
      fence: fence,
      source_lines: body,
      source: Enum.join(body, "\n"),
      line: n + 1,
      outputs: []
    }

    tokens(rest, [{:cell, cell} | acc])
  end

  # A fenced block that is not a cell (mermaid, text, a bare fence, ...).
  # Everything through the closing fence is markdown.
  defp fenced_markdown([{open, _} | rest], acc) do
    [_, fence] = Regex.run(@any_fence, open)
    {body, rest} = take_until_fence(rest, fence)
    acc = Enum.reduce(body, [{:md, open} | acc], fn l, acc -> [{:md, l} | acc] end)

    case rest do
      [] -> tokens([], acc)
      [{close, _} | rest] -> tokens(rest, [{:md, close} | acc])
    end
  end

  defp take_output(lines) do
    {_blanks, rest} = Enum.split_while(lines, fn {l, _} -> l == "" end)

    with [{open, _} | rest] <- rest,
         [_, fence] <- Regex.run(@plain_fence, open),
         {body, [{_close, _} | rest]} <- take_until_fence(rest, fence) do
      {:ok, Enum.join(body, "\n"), rest}
    else
      _ -> :error
    end
  end

  # Returns `{body_lines, rest}` where `rest` starts with the closing
  # fence line, or is `[]` when the fence is never closed.
  defp take_until_fence(lines, fence) do
    {body, rest} = Enum.split_while(lines, fn {l, _} -> String.trim_trailing(l) != fence end)
    {Enum.map(body, &elem(&1, 0)), rest}
  end

  # -- grouping ------------------------------------------------------------

  defp group([], acc), do: Enum.reverse(acc)

  defp group([{:md, line} | rest], [%{type: :markdown, lines: lines} = md | acc]) do
    group(rest, [%{md | lines: lines ++ [line]} | acc])
  end

  defp group([{:md, line} | rest], acc) do
    group(rest, [%{type: :markdown, lines: [line]} | acc])
  end

  defp group([{:cell, cell} | rest], acc), do: group(rest, [cell | acc])

  defp group([{:output, text} | rest], acc) do
    case attach_output(acc, text) do
      {:ok, acc} -> group(rest, acc)
      :error -> group(rest, acc)
    end
  end

  # Attach to the preceding cell when only blank lines separate them. The
  # blank lines are dropped: `render/1` puts them back.
  defp attach_output([%{type: :markdown, lines: lines} | [%{type: :cell} | _] = acc], text) do
    if Enum.all?(lines, &(&1 == "")), do: attach_output(acc, text), else: :error
  end

  defp attach_output([%{type: :cell} = cell | acc], text) do
    {:ok, [%{cell | outputs: cell.outputs ++ [text]} | acc]}
  end

  defp attach_output(_acc, _text), do: :error

  # -- rendering -----------------------------------------------------------

  defp block_lines(%{type: :markdown, lines: lines}), do: lines

  defp block_lines(%{type: :cell} = cell) do
    cell.metadata ++
      [cell.fence <> "elixir"] ++
      cell.source_lines ++
      [cell.fence] ++
      output_lines(cell.outputs)
  end

  defp output_lines([]), do: []

  defp output_lines(outputs) do
    ["" | outputs |> Exhibit.Runner.Output.text_blocks() |> String.split("\n")]
  end
end

defmodule Exhibit.Runner.Output do
  @moduledoc """
  Serialises cell outputs the way Livebook persists them.

  Mirrors `Livebook.LiveMarkdown.Export`: each text output is an
  `<!-- livebook:{"output":true} -->` comment, a blank line, and a code
  fence whose delimiter is longer than any run of backticks in the body.
  ANSI escapes are stripped and one trailing newline is removed.
  """

  @output_comment ~s(<!-- livebook:{"output":true} -->)
  @persist_header ~s(<!-- livebook:{"persist_outputs":true} -->)

  @ansi ~r/\e\[[\d;?]*[ -\/]*[@-~]/

  @doc "The notebook-level comment that tells Livebook to keep outputs in the file."
  @spec persist_outputs_header() :: String.t()
  def persist_outputs_header, do: @persist_header

  @doc "The comment that introduces a persisted output."
  @spec output_comment() :: String.t()
  def output_comment, do: @output_comment

  @doc "Removes ANSI escape sequences."
  @spec strip_ansi(String.t()) :: String.t()
  def strip_ansi(text), do: Regex.replace(@ansi, text, "")

  @doc """
  A fence delimiter one backtick longer than the longest run of three or
  more backticks in `code`, and never shorter than three.
  """
  @spec code_block_delimiter(String.t()) :: String.t()
  def code_block_delimiter(code) do
    max_streak =
      ~r/`{3,}/
      |> Regex.scan(code)
      |> Enum.map(fn [run] -> byte_size(run) end)
      |> Enum.max(&>=/2, fn -> 2 end)

    String.duplicate("`", max_streak + 1)
  end

  @doc """
  Renders one terminal-text output as Livebook persists it. The returned
  string has no trailing newline.
  """
  @spec text_block(String.t()) :: String.t()
  def text_block(text) do
    text = text |> strip_ansi() |> String.replace_suffix("\n", "")
    delimiter = code_block_delimiter(text)
    Enum.join([@output_comment, "", delimiter, text, delimiter], "\n")
  end

  @doc "Renders a cell's outputs, separated by blank lines."
  @spec text_blocks([String.t()]) :: String.t()
  def text_blocks(texts), do: Enum.map_join(texts, "\n\n", &text_block/1)

  @doc """
  Makes sure the document opens with notebook metadata that sets
  `persist_outputs` to true, so Livebook keeps the outputs we wrote.
  """
  @spec ensure_persist_outputs(String.t()) :: String.t()
  def ensure_persist_outputs(doc) do
    case String.split(doc, "\n", parts: 2) do
      [first, rest] when first != @persist_header ->
        if notebook_metadata?(first) do
          enable_persist(first) <> "\n" <> rest
        else
          @persist_header <> "\n\n" <> doc
        end

      [first] when first != @persist_header ->
        @persist_header <> "\n\n" <> doc

      _ ->
        doc
    end
  end

  defp notebook_metadata?(line) do
    String.starts_with?(line, "<!-- livebook:{") and String.ends_with?(line, "} -->")
  end

  defp enable_persist(line) do
    cond do
      String.contains?(line, ~s("persist_outputs":true)) ->
        line

      String.contains?(line, ~s("persist_outputs":false)) ->
        String.replace(line, ~s("persist_outputs":false), ~s("persist_outputs":true))

      line == "<!-- livebook:{} -->" ->
        @persist_header

      true ->
        String.replace(line, "<!-- livebook:{", ~s(<!-- livebook:{"persist_outputs":true,),
          global: false
        )
    end
  end
end

defmodule Exhibit.Runner do
  @moduledoc """
  Evaluates the Elixir cells of a notebook in order, inside the current VM,
  and writes Livebook-format outputs back into the file.

  This module is the heart of `priv/runner.exs`, which `mix
  exhibit.build_runner` assembles from `lib/` so a target project can run
  it with `MIX_ENV=test mix run priv/runner.exs NOTEBOOK` and no extra
  dependency.

  Cells share one binding and one evaluation environment, so `alias`,
  `import`, `require` and variables carry over, as in Livebook. Standard
  output is captured per cell by pointing the group leader at a `StringIO`.
  A cell that raises, throws or exits gets the formatted error as its
  output; later cells are left without outputs and the run fails.
  """

  alias Exhibit.Runner.Output
  alias Exhibit.Runner.Parser

  @max_frames 8

  @doc "Entry point of the generated script: `mix run runner.exs NOTEBOOK`."
  @spec main([String.t()]) :: :ok | no_return()
  def main([path]) do
    case run(path) do
      :ok -> :ok
      {:error, _reason} -> System.halt(1)
    end
  end

  def main(_args) do
    IO.puts(:stderr, "usage: mix run runner.exs NOTEBOOK")
    System.halt(2)
  end

  @doc """
  Runs every cell of the notebook at `path` and rewrites the file with
  outputs. Returns `:ok`, or `{:error, message}` if a cell failed; the
  file is written in both cases.

  Options:

    * `:project` - the root of the project the cells run in, used to trim
      stacktraces. Defaults to the current directory.
  """
  @spec run(Path.t(), keyword()) :: :ok | {:error, String.t()}
  def run(path, opts \\ []) do
    project = Keyword.get(opts, :project, File.cwd!())
    path = Path.expand(path)
    blocks = path |> File.read!() |> Parser.parse()

    {blocks, status} = evaluate(blocks, path, project)

    doc = blocks |> Parser.render() |> Output.ensure_persist_outputs()
    write_atomically(path, doc)
    status
  end

  defp evaluate(blocks, path, project) do
    env = Code.env_for_eval(file: path)

    {blocks, {_index, state}} =
      Enum.map_reduce(blocks, {1, {:ok, [], env}}, fn
        %{type: :cell} = cell, {index, {:ok, binding, env}} ->
          {outputs, state} = eval_cell(cell, index, binding, env, path, project)
          {%{cell | outputs: outputs}, {index + 1, state}}

        %{type: :cell} = cell, {index, {:halted, _} = state} ->
          {%{cell | outputs: []}, {index + 1, state}}

        block, acc ->
          {block, acc}
      end)

    case state do
      {:ok, _binding, _env} -> {blocks, :ok}
      {:halted, message} -> {blocks, {:error, message}}
    end
  end

  defp eval_cell(cell, index, binding, env, path, project) do
    IO.puts("== cell #{index} (line #{cell.line})")

    {result, stdout} =
      capture_stdout(fn ->
        try do
          quoted = Code.string_to_quoted!(cell.source, file: path, line: cell.line)
          {:ok, Code.eval_quoted_with_env(quoted, binding, env)}
        catch
          kind, payload -> {:error, kind, payload, __STACKTRACE__}
        end
      end)

    stdout_outputs = if stdout == "", do: [], else: [stdout]

    case result do
      {:ok, {value, binding, env}} ->
        outputs = stdout_outputs ++ [inspect(value, pretty: true, width: 80)]
        print_outputs(outputs)
        {outputs, {:ok, binding, env}}

      {:error, kind, payload, stacktrace} ->
        message = Exception.format(kind, payload, trim_stacktrace(stacktrace, path, project))
        outputs = stdout_outputs ++ [message]
        print_outputs(outputs)
        IO.puts(:stderr, "exhibit: cell #{index} (line #{cell.line}) failed\n#{message}")
        {outputs, {:halted, message}}
    end
  end

  defp capture_stdout(fun) do
    {:ok, io} = StringIO.open("")
    leader = Process.group_leader()
    Process.group_leader(self(), io)

    result =
      try do
        fun.()
      after
        Process.group_leader(self(), leader)
      end

    {_input, output} = StringIO.contents(io)
    StringIO.close(io)
    {result, output}
  end

  defp print_outputs(outputs) do
    Enum.each(outputs, fn text ->
      IO.puts(text |> Output.strip_ansi() |> String.replace_suffix("\n", ""))
    end)
  end

  # Keep the frame that raised plus frames in the notebook or the project,
  # drop our own frames and everything in Elixir, OTP or dependencies.
  defp trim_stacktrace(stacktrace, path, project) do
    stacktrace
    |> Enum.reject(&runner_frame?/1)
    |> Enum.with_index()
    |> Enum.filter(fn {frame, i} -> i == 0 or project_frame?(frame, path, project) end)
    |> Enum.map(&elem(&1, 0))
    |> Enum.take(@max_frames)
  end

  defp runner_frame?({module, _fun, _arity, _info}) when is_atom(module) do
    module |> Atom.to_string() |> String.starts_with?("Elixir.Exhibit.Runner")
  end

  defp runner_frame?(_frame), do: false

  defp project_frame?({_module, _fun, _arity, info}, path, project) do
    case Keyword.get(info, :file) do
      nil ->
        false

      file ->
        file = to_string(file)
        file == path or File.exists?(Path.expand(file, project))
    end
  end

  defp project_frame?(_frame, _path, _project), do: false

  defp write_atomically(path, content) do
    tmp =
      Path.join(
        Path.dirname(path),
        ".#{Path.basename(path)}.#{System.unique_integer([:positive])}.tmp"
      )

    File.write!(tmp, content)
    File.rename!(tmp, path)
  end
end

Exhibit.Runner.main(System.argv())
